def transform(grid):
    boxes={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v:
                if v not in boxes: boxes[v]=[r,r,c,c]
                b=boxes[v]
                b[0]=min(b[0],r); b[1]=max(b[1],r); b[2]=min(b[2],c); b[3]=max(b[3],c)
    bs=list(boxes.values())
    overlap=any(max(a[0],b[0])<=min(a[1],b[1]) and max(a[2],b[2])<=min(a[3],b[3]) for i,a in enumerate(bs) for b in bs[i+1:])
    color=5 if overlap else 8
    return [[color if v else 0 for v in row] for row in grid]

